 (out/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'status':status,'candidates':len(candidates),'languages':dict(sorted(candidate_languages.items())),'report':str((out/'REPORT.md').relative_to(REPO_ROOT))}))
